import React, { useState, useEffect, useRef } from 'react'
import { useNavigate } from "react-router-dom"
import "./Header.scss"
import { CircleUserRound, LogOut } from 'lucide-react'

const Header = () => {
  const navigate = useNavigate();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false)
  const dropdownRef = useRef(null)

  const toggleDropdown = () => {
    setIsDropdownOpen(!isDropdownOpen) // profile click reveals or hides dropdown
  }

  const handleClickOutside = (e) => {
    if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
      setIsDropdownOpen(false)
    }
  }

  useEffect(() => {
    if (isDropdownOpen) {
      document.addEventListener('mousedown', handleClickOutside)
    } else {
      document.removeEventListener('mousedown', handleClickOutside)
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [isDropdownOpen])

  return (
    <div className="header-container">
      <div className="header-section-container">
        <div className="profile-container">
          <CircleUserRound className="profile-icon" onClick={toggleDropdown}/>
          {isDropdownOpen && (
            <div className='profile-menu-container' ref={dropdownRef}>
              <ul className='dropdown-container'>
                <li className='dropdown-top'>
                  <div className='profile-outline'></div>
                </li>
                <li className='dropdown-link-container' onClick={() => navigate('/profile')}>
                  <label className='dropdown-item-container'>Profile</label>
                </li>
                <li className='dropdown-link-container' onClick={() => navigate('/settings')}>
                  <label className='dropdown-item-container'>Settings</label>
                </li>
                <li className='dropdown-link-container' onClick={() => navigate('/logout')}>
                  <label className='dropdown-item-container'>Logout <LogOut /></label>
                </li>
              </ul>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

export default Header
